package br.com.onda;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class MenuPanelTest {
 private final Instrumentation ins=getInstrumentation();private Activity activity;private Dialog dialog;
 private View find(View v,String desc){if(android.text.TextUtils.equals(desc,v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View match=find(((ViewGroup)v).getChildAt(i),desc);if(match!=null)return match;}return null;}
 private View root(){return dialog.findViewById(android.R.id.content);}
 @After public void after(){ins.runOnMainSync(()->{if(dialog!=null)dialog.dismiss();if(activity!=null)activity.finish();});ins.waitForIdleSync();}
 @Test public void categoryAndAccentSearchKeepActionsCorrect()throws Exception{Context c=ins.getTargetContext();activity=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));AtomicInteger selected=new AtomicInteger(-1);String[] labels={"Estúdio de som","Fones e Bluetooth","Downloads","Playlists","Aparências","Leitor de PDF","Temporizador","Atualizações","Imagens e mensagens","Conversor local","Minhas frases","Compartilhar música atual"};Runnable[] actions=new Runnable[labels.length];for(int i=0;i<actions.length;i++){final int index=i;actions[i]=()->selected.set(index);}ins.runOnMainSync(()->{Button anchor=Ui.button(activity,"Menu",null);anchor.setContentDescription("Menu da biblioteca");dialog=MenuPanel.show(activity,anchor,labels,labels,actions);((Spinner)find(root(),"Categoria do menu")).setSelection(4);});ins.waitForIdleSync();ins.runOnMainSync(()->{assertEquals(View.GONE,find(root(),"Downloads").getVisibility());assertEquals(View.VISIBLE,find(root(),"Estúdio de som").getVisibility());((EditText)find(root(),"Buscar no menu")).setText("FONES");assertEquals(View.GONE,find(root(),"Estúdio de som").getVisibility());assertEquals(View.VISIBLE,find(root(),"Fones e Bluetooth").getVisibility());find(root(),"Fones e Bluetooth").performClick();assertFalse(dialog.isShowing());assertEquals(1,selected.get());});}
 @Test public void savedShortcutsAndAppearanceFiltersSurviveReopening()throws Exception{Context c=ins.getTargetContext();String key="Menu do teste";String old=c.getSharedPreferences("menu_shortcuts",0).getString(key,null);boolean hadPreview=c.getSharedPreferences("appearance",0).contains("show_previews"),oldPreview=c.getSharedPreferences("appearance",0).getBoolean("show_previews",true);AtomicInteger action=new AtomicInteger();try{String[] names={"Downloads","Leitor de PDF","Aparências"};MenuPanel.save(c,key,names,new boolean[]{false,true,false});activity=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.runOnMainSync(()->{Button anchor=Ui.button(activity,"Menu",null);anchor.setContentDescription(key);dialog=MenuPanel.show(activity,anchor,names,names,new Runnable[]{()->{},action::incrementAndGet,()->{}});assertNotNull(find(root(),"Atalho: Leitor de PDF"));find(root(),"Atalho: Leitor de PDF").performClick();assertEquals(1,action.get());activity.finish();});activity=ins.startActivitySync(new Intent(c,AppearanceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.runOnMainSync(()->{View root=activity.findViewById(android.R.id.content);((EditText)find(root,"Buscar aparência")).setText("TITANIO");assertTrue(find(root,"Usar aparência Titânio 3D").isShown());assertFalse(find(root,"Usar aparência Aurora 3D").isShown());((Switch)find(root,"Exibir prévias das aparências")).setChecked(false);assertFalse(c.getSharedPreferences("appearance",0).getBoolean("show_previews",true));activity.finish();});activity=ins.startActivitySync(new Intent(c,AppearanceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.runOnMainSync(()->assertFalse(((Switch)find(activity.findViewById(android.R.id.content),"Exibir prévias das aparências")).isChecked()));}finally{SharedPreferences.Editor e=c.getSharedPreferences("menu_shortcuts",0).edit();if(old==null)e.remove(key);else e.putString(key,old);e.commit();e=c.getSharedPreferences("appearance",0).edit();if(hadPreview)e.putBoolean("show_previews",oldPreview);else e.remove("show_previews");e.commit();}}
}
